function CountVowels(s: string): int
    reads s
    requires s != null
    ensures result >= 0
{
    var count := 0;
    var length := s.Length;
    var i := 0;

    while i < length
        invariant 0 <= i <= length
        invariant count == CountVowels(s[..i])
    {
        if IsVowel(s[i], i == length - 1) {
            count := count + 1;
        }
        i := i + 1;
    }

    return count;
}

